"""Tests for the grid-city ambulance dispatch simulator (seed 31)."""

import time

import pytest

from ambulance_sim import (
    BASES,
    SIM_HOURS,
    Simulator,
    generate_calls,
    run_simulation,
)

SEED = 31


def _run(n_units: int):
    return run_simulation(seed=SEED, n_units=n_units)


# ---------------------------------------------------------------------------
# Fixtures: run each scenario once, reuse across tests
# ---------------------------------------------------------------------------

@pytest.fixture(scope="module")
def four_units():
    return _run(4)


@pytest.fixture(scope="module")
def one_unit():
    return _run(1)


# ---------------------------------------------------------------------------
# Tests
# ---------------------------------------------------------------------------

def test_four_units_mean_response_under_15(four_units):
    r = four_units
    assert r.n_calls > 150          # ~216 expected arrivals in 72h
    assert r.n_served == r.n_calls  # everything eventually served
    assert r.mean_response < 15.0


def test_four_units_p90_response_under_25(four_units):
    assert four_units.p90_response() < 25.0


def test_one_unit_strictly_worse_than_four(four_units, one_unit):
    m4, p4 = four_units.mean_response, four_units.p90_response()
    m1, p1 = one_unit.mean_response, one_unit.p90_response()
    assert m1 > m4, f"mean: 1 unit ({m1:.1f}) must exceed 4 units ({m4:.1f})"
    assert p1 > p4, f"P90: 1 unit ({p1:.1f}) must exceed 4 units ({p4:.1f})"


def test_no_double_assignment_invariant(four_units):
    """The engine asserts this internally; here we verify it independently by
    counting concurrent assignments from per-unit busy intervals."""
    r = four_units
    assert r.max_concurrent_assignments <= r.n_units

    # Reconstruct a concurrency timeline from the logged intervals.
    points = []
    for u, intervals in r.unit_busy_intervals.items():
        for start, end in intervals:
            assert end is not None and end >= start
            points.append((start, 1, u))
            points.append((end, -1, u))
    points.sort(key=lambda p: (p[0], p[1]))
    live = peak = 0
    for _, delta, _u in points:
        live += delta
        peak = max(peak, live)
    assert peak == r.max_concurrent_assignments
    assert peak <= len(BASES)


def test_no_overlapping_intervals_per_unit(four_units):
    """A single unit's busy intervals must never overlap."""
    for u, intervals in four_units.unit_busy_intervals.items():
        intervals = sorted(intervals)
        for (s1, e1), (s2, e2) in zip(intervals, intervals[1:]):
            assert s2 >= e1, f"unit {u} double-assigned: [{s1},{e1}] vs [{s2},{e2}]"


def test_queue_drains_after_arrivals_stop(four_units):
    r = four_units
    assert r.queue_len_at_end == 0
    assert r.busy_at_end == 0
    assert r.sim_end_min > SIM_HOURS * 60.0  # ran past the last arrival
    assert r.n_served == r.n_calls


def test_one_unit_queue_also_drains(one_unit):
    assert one_unit.queue_drained


def test_deterministic_per_seed():
    a = _run(4)
    b = _run(4)
    assert a.response_times_min == b.response_times_min
    assert a.n_calls == b.n_calls
    assert generate_calls(SEED) == generate_calls(SEED)


def test_different_seed_gives_different_arrivals():
    assert generate_calls(31) != generate_calls(7)


def test_runtime_under_30_seconds():
    t0 = time.perf_counter()
    for n in (1, 2, 4):
        run_simulation(seed=SEED, n_units=n)
    elapsed = time.perf_counter() - t0
    assert elapsed < 30.0, f"three full runs took {elapsed:.1f}s"

